function insert(source, line) {
  const start = source.indexOf("// zudojs:routes:start");
  const end = source.indexOf("// zudojs:routes:end");
  if (start === -1 || end === -1) return "missing-markers";
  if (source.slice(start, end).includes(line)) return "present";
  return "inserted";
}

