function validateBookingDate(input) {
  if (typeof input !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(input)) return false;
  const date = new Date(`${input}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === input;
}

for (const input of ["2026-12-24", "2026-02-30", "2028-02-29", "24/12/2026", 20261224]) {
  console.log(input, validateBookingDate(input));
}

