const records = new Map();

async function create(input) {
  for (const record of records.values()) {
    if (record.hallId === input.hallId && record.date === input.date) throw new Error("taken");
  }
  const record = { id: records.size + 1, ...input };
  records.set(record.id, record);
  return record;
}

const input = { hallId: "eko", date: "2026-12-24", customerEmail: "ada@example.com" };
const results = await Promise.allSettled([create(input), create({ ...input, customerEmail: "tunde@example.com" })]);
